@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode <https://heritalise-eccch.eu/resource/observation/legacy-rh-reading-001> ;
            sh:resultMessage "sosa:resultTime or sosa:phenomenonTime is required, and no more than 1 of each is allowed" ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraint [ sh:message "sosa:resultTime or sosa:phenomenonTime is required, and no more than 1 of each is allowed" ;
                    sh:select """
            PREFIX sh: <http://www.w3.org/ns/shacl#>
            PREFIX sosa: <http://www.w3.org/ns/sosa/>
            PREFIX geojson: <https://purl.org/geojson/vocab#>
            SELECT $this (CONCAT(COALESCE(COUNT(?resultTime), 0), ' x sosa:resultTime, ', COALESCE(COUNT(?phenomenonTime), 0), ' x sosa:phenomenonTime') AS ?value) WHERE {
                OPTIONAL { $this sosa:phenomenonTime ?phenomenonTime }
                OPTIONAL { $this sosa:resultTime ?resultTime}
                OPTIONAL { $this sosa:startTime ?startTime }
                OPTIONAL { $this sosa:endTime ?endTime }
                OPTIONAL { ?collection (sosa:hasMember|geojson:features)+ $this ; sosa:phenomenonTime ?phenomenonTime }
                OPTIONAL { ?collection (sosa:hasMember|geojson:features)+ $this ; sosa:resultTime ?resultTime }
                OPTIONAL { ?collection (sosa:hasMember|geojson:features)+ $this ; sosa:startTime ?startTime }
                OPTIONAL { ?collection (sosa:hasMember|geojson:features)+ $this ; sosa:endTime ?endTime }
            }
            GROUP BY $this
            HAVING (count(?resultTime) > 1 || count(?phenomenonTime) > 1 || count(?resultTime) + count(?phenomenonTime) + count(?startTime) + count(?endTime) < 1)
        """ ] ;
            sh:sourceConstraintComponent sh:SPARQLConstraintComponent ;
            sh:sourceShape <https://www.ogc.org/rules/sosa/#testRequiredTime> ;
            sh:value <https://heritalise-eccch.eu/resource/observation/legacy-rh-reading-001> ] .

